/**
 * Compile-time drift check between the hand-written client types (types.ts) and the
 * backend's OpenAPI schema (schema.d.ts, generated by `pnpm gen:api`).
 * If the backend contract changes, `pnpm typecheck` fails here. No runtime code.
 */
import type { components } from './schema'
import type * as T from './types'

type S = components['schemas']

/** Resolves to `true` only if A and B are mutually assignable. */
type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false
/** Request bodies: what the client sends must be accepted by the server schema. */
type Accepts<Server, Client> = [Client] extends [Server] ? true : false

function check<_ extends true>(): void {}

// Responses: the server shape must satisfy what the client reads.
check<Same<T.Company, S['Company']>>()
check<Accepts<T.Agent, S['Agent']>>()
check<Accepts<T.Department, S['Department']>>()
check<Accepts<T.AuditEvent, S['AuditEvent']>>()
check<Accepts<T.Health, S['Health']>>()
check<Accepts<T.Me, S['Me']>>()
check<Accepts<T.RuntimeInfo, S['RuntimeInfo']>>()

// Requests: the server must accept everything the client sends.
check<Accepts<S['CompanyCreate'], T.CreateCompanyRequest>>()
check<Accepts<S['CompanyUpdate'], T.UpdateCompanyRequest>>()
check<Accepts<S['AgentCreate'], T.CreateAgentRequest>>()
check<Accepts<S['AgentUpdate'], T.UpdateAgentRequest>>()
check<Accepts<S['DepartmentCreate'], T.CreateDepartmentRequest>>()
check<Accepts<S['DepartmentUpdate'], T.UpdateDepartmentRequest>>()

// ---- Milestone 2 (work engine) ----
check<Accepts<T.AgentLive, S['AgentLive']>>()
check<Accepts<T.CompanyPolicy, S['Policy']>>()
check<Accepts<T.Goal, S['Goal']>>()
check<Accepts<T.Project, S['Project']>>()
check<Accepts<T.Task, S['Task']>>()
check<Accepts<T.TaskRun, S['TaskRun']>>()
check<Accepts<T.RunEvent, S['RunEvent']>>()
check<Accepts<T.Artifact, S['Artifact']>>()
check<Accepts<T.ArtifactVersion, S['ArtifactVersion']>>()
check<Accepts<T.Approval, S['Approval']>>()
check<Accepts<T.Decision, S['Decision']>>()
check<Accepts<T.Schedule, S['Schedule']>>()

check<Accepts<S['PolicyUpdate'], T.UpdatePolicyRequest>>()
check<Accepts<S['GoalCreate'], T.CreateGoalRequest>>()
check<Accepts<S['GoalUpdate'], T.UpdateGoalRequest>>()
check<Accepts<S['ProjectCreate'], T.CreateProjectRequest>>()
check<Accepts<S['ProjectUpdate'], T.UpdateProjectRequest>>()
check<Accepts<S['TaskCreate'], T.CreateTaskRequest>>()
check<Accepts<S['TaskUpdate'], T.UpdateTaskRequest>>()

// ---- Milestone 4 (skills & HR) ----
check<Accepts<T.Skill, S['Skill']>>()
check<Accepts<T.SkillDetail, S['SkillDetail']>>()
check<Accepts<T.SkillAssignedAgent, S['SkillAssignedAgent']>>()
check<Accepts<T.SkillFileInfo, S['SkillFileInfo']>>()
check<Accepts<T.SkillFileContent, S['SkillFileContent']>>()
check<Accepts<T.CatalogItem, S['CatalogItem']>>()
check<Accepts<T.InstallSkillResult, S['SkillInstallResult']>>()
check<Accepts<T.AgentSkill, S['AgentSkill']>>()
check<Accepts<T.RoleTemplate, S['RoleTemplate']>>()
// The enums the UI switches on must be exactly the server's.
check<Same<T.SkillSourceKind, S['Skill']['source_kind']>>()
check<Same<T.SkillTrust, S['Skill']['trust']>>()
check<Same<T.ScanVerdict, S['Skill']['scan_verdict']>>()
check<Same<T.SkillStatus, S['Skill']['status']>>()
check<Same<T.RoleFamily, S['RoleTemplate']['family']>>()

check<Accepts<S['SkillInstall'], T.InstallSkillRequest>>()
check<Accepts<S['SkillRefs'], T.AssignSkillsRequest>>()
// Hiring from a role template: AgentCreate now takes `role_template` and `skill_slugs`.
check<Accepts<S['AgentCreate'], Required<Pick<T.CreateAgentRequest, 'role_template' | 'skill_slugs'>> & T.CreateAgentRequest>>()

// ---- Milestone 3b (model providers, credentials) ----
// These endpoints are specified in prose only and were not in the OpenAPI schema when the UI was written
// (types.ts "Milestone 3b" documents the assumed shapes). Each check below switches itself on as soon as
// `pnpm gen:api` brings the schema in, and then fails typecheck on any drift.
type WhenInSchema<K extends string, Check extends boolean> = K extends keyof S ? Check : true
check<WhenInSchema<'ModelProvider', Accepts<T.ModelProvider, S[Extract<'ModelProvider', keyof S>]>>>()
check<WhenInSchema<'ModelProviderCreate', Accepts<S[Extract<'ModelProviderCreate', keyof S>], T.CreateModelProviderRequest>>>()
check<WhenInSchema<'Credential', Accepts<T.Credential, S[Extract<'Credential', keyof S>]>>>()
check<WhenInSchema<'CredentialCreate', Accepts<S[Extract<'CredentialCreate', keyof S>], T.CreateCredentialRequest>>>()

// ---- Milestone 5 (Founder's notes, AI Co-founder, memory, alerts) ----
// The M5 backend does not exist yet; types.ts "Milestone 5" documents the assumed shapes. The schema names
// below are the expected ones (docs/specs/m5-autonomous-company.md §7). Each check switches itself on when a
// schema with that name appears after `pnpm gen:api`, and then fails typecheck on any drift.
check<WhenInSchema<'FounderNote', Accepts<T.FounderNote, S[Extract<'FounderNote', keyof S>]>>>()
check<WhenInSchema<'NoteDetail', Accepts<T.NoteDetail, S[Extract<'NoteDetail', keyof S>]>>>()
check<WhenInSchema<'NoteReply', Accepts<T.NoteReply, S[Extract<'NoteReply', keyof S>]>>>()
check<WhenInSchema<'NoteCreate', Accepts<S[Extract<'NoteCreate', keyof S>], T.CreateNoteRequest>>>()
check<WhenInSchema<'NoteReplyCreate', Accepts<S[Extract<'NoteReplyCreate', keyof S>], T.CreateNoteReplyRequest>>>()
check<WhenInSchema<'NoteUpdate', Accepts<S[Extract<'NoteUpdate', keyof S>], T.UpdateNoteRequest>>>()
check<WhenInSchema<'Alert', Accepts<T.Alert, S[Extract<'Alert', keyof S>]>>>()
check<WhenInSchema<'MemoryEntry', Accepts<T.MemoryEntry, S[Extract<'MemoryEntry', keyof S>]>>>()
check<WhenInSchema<'MemoryCreate', Accepts<S[Extract<'MemoryCreate', keyof S>], T.CreateMemoryRequest>>>()
check<WhenInSchema<'CofounderSummary', Accepts<T.CofounderSummary, S[Extract<'CofounderSummary', keyof S>]>>>()
